// The old Hugo theme registered a service worker at /sw.min.js. This replacement
// deletes that theme's caches, unregisters itself and reloads open pages, so old
// visitors get the live site. Keep this file in place.
const OLD_CACHES = ['assets-v1', 'content-v1', 'offline-v1', '404-v1'];
self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', e => e.waitUntil((async () => {
  await Promise.all(OLD_CACHES.map(k => caches.delete(k)));
  await self.registration.unregister();
  for (const c of await self.clients.matchAll({type: 'window'})) c.navigate(c.url);
})()));
